private static void stretchMove(Unit unit, UPoint capturedPoint, float destX, float destY) {
    Preconditions.checkState(!capturedPoint.isBase());
    float f = destX - capturedPoint.x;
    float f2 = destY - capturedPoint.y;
    capturedPoint.x = destX;
    capturedPoint.y = destY;
    SlavesRegistry slavesRegistry = unit.getOwnFrame().mSlavesStr;
    Unit slave = slavesRegistry.getSlave(capturedPoint);
    if (slave != null) {
        slave.mState.shiftBy(f, f2, true);
    }
    for (UPoint uPoint : unit.mDescendants.get(Integer.valueOf(capturedPoint.getId()))) {
        uPoint.x += f;
        uPoint.y += f2;
        Unit slave2 = slavesRegistry.getSlave(uPoint);
        if (slave2 != null) {
            slave2.mState.shiftBy(f, f2, true);
        }
    }
}
